def transform(g):
    h,w=len(g),len(g[0])
    cand_rows={i for i in range(h) if len(set(g[i]))==1}
    cand_cols={j for j in range(w) if len({g[i][j] for i in range(h)})==1}
    def in_cand(i,j):
        return i in cand_rows or j in cand_cols
    sep_rows=set(); sep_cols=set()
    for v in {x for r in g for x in r}:
        cells=[(i,j) for i in range(h) for j in range(w) if g[i][j]==v]
        if all(in_cand(i,j) for i,j in cells):
            sep_rows |= {i for i in cand_rows if g[i][0]==v}
            sep_cols |= {j for j in cand_cols if g[0][j]==v}
    row_bounds=[]; prev=0
    for i in sorted(sep_rows)+[h]:
        if i>prev: row_bounds.append((prev,i))
        prev=i+1
    col_bounds=[]; prev=0
    for j in sorted(sep_cols)+[w]:
        if j>prev: col_bounds.append((prev,j))
        prev=j+1
    regions=[(r0,r1,c0,c1) for r0,r1 in row_bounds for c0,c1 in col_bounds]
    def uniform(r):
        r0,r1,c0,c1=r
        return len({g[i][j] for i in range(r0,r1) for j in range(c0,c1)})==1
    blocks=[r for r in regions if not uniform(r)]
    assert len(blocks)==1, blocks
    b0=blocks[0]; br0,br1,bc0,bc1=b0
    src=[[g[i][j] for j in range(bc0,bc1)] for i in range(br0,br1)]
    out=[row[:] for row in g]
    bh,bw=len(src),len(src[0])
    for r in regions:
        if r==b0: continue
        r0,r1,c0,c1=r
        for i in range(r0,r1):
            for j in range(c0,c1):
                out[i][j]=src[(i-r0)%bh][(j-c0)%bw]
    return out

